### 4) No rate limiting / abuse controls (OWASP A04: Insecure Design, also A05)
**Issue:** Endpoints can be scraped or hammered (especially `/users`).

**Recommendation:** Add rate limiting (and potentially IP allowlisting if appropriate).

**Example: express-rate-limit**
```js
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 60 * 1000,
  limit: 60,
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(apiLimiter);
```

---

### 5) Missing input validation (currently low risk, but add patterns before you grow)
**Issue:** Today there’s no user input. But once you add query params (e.g., `/users?search=`), you’ll need validation to prevent injection and logic abuse.

**Recommendation:** Adopt a validation library early (Joi, Zod, express-validator) and apply it systematically to params/query/body.

**Example: validating a query param (express-validator)**
```js
const { query, validationResult } = require('express-validator');

app.get('/users',
  requireJwt,
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const limit = req.query.limit ?? 20;
    // use limit safely
    res.json(/* ... */);
  }
);
```

---

### 6) Logging & monitoring gaps (OWASP A09: Security Logging and Monitoring Failures)
**Issue:** Only logs “Server running…” No request logging, no audit logs for sensitive endpoints, no security-relevant event tracking.

**Recommendations:**
- Add structured request logging (e.g., `morgan` or `pino-http`).
- Log auth failures, access denials, and rate-limit events (without logging secrets).

**Example: morgan**
```js
const morgan = require('morgan');
app.use(morgan('combined'));
```

---

### 7) Error handling / safe failure (OWASP A05)
**Issue:** No centralized error handler. As routes grow, unhandled exceptions can crash the process or leak stack traces.

**Recommendation:** Add an error-handling middleware; avoid leaking internals in production.

**Example:**
```js
app.use((err, req, res, next) => {
  // log err internally
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});
```

---

### 8) Environment/config safety
**Issue:** Port is hardcoded to `3000`. Not a vulnerability by itself, but configuration should be environment-driven. Also ensure secrets are not committed and are loaded safely.

**Recommendation:**
```js
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

---

## “Secure-by-default” revised `app.js` (example)
This is a consolidated example showing the recommended baseline controls (auth stub, headers, rate limit, logging). Adjust to your needs.

```js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

app.disable('x-powered-by');
app.use(helmet());
app.use(express.json({ limit: '100kb' })); // useful once you add POST/PUT
app.use(morgan('combined'));

app.use(cors({
  origin: ['https://your-frontend.example.com'],
  methods: ['GET'],
}));

app.use(rateLimit({
  windowMs: 60 * 1000,
  limit: 60,
  standardHeaders: true,
  legacyHeaders: false,
}));

function requireApiKey(req, res, next) {
  const apiKey = req.get('x-api-key');
  if (!apiKey || apiKey !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', requireApiKey, (req, res) => {
  // minimize sensitive fields by default
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// central error handler
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

